function maalemContrastFix(){
 const rgb=s=>{let m=s.match(/rgba?\(([^)]+)\)/);return m?m[1].split(',').map(Number):null};
 const lum=c=>{let v=c.slice(0,3).map(x=>{x/=255;return x<=.04045?x/12.92:Math.pow((x+.055)/1.055,2.4)});return .2126*v[0]+.7152*v[1]+.0722*v[2]};
 function bg(e){for(let n=e;n&&n.nodeType===1;n=n.parentElement){let st=getComputedStyle(n),g=st.backgroundImage;let c=rgb(g!=='none'?g:st.backgroundColor);if(c&&(c.length<4||c[3]>.85))return c}return [255,255,255]}
 document.querySelectorAll('body *').forEach(e=>{if(e.closest('script,style,site-header')||['IMG','VIDEO','CANVAS'].includes(e.tagName))return;let s=getComputedStyle(e),c=rgb(s.color),b=bg(e);if(!c||lum(b)>.18)return;let ratio=(Math.max(lum(c),lum(b))+.05)/(Math.min(lum(c),lum(b))+.05);if(ratio<4.5)e.style.setProperty('color',/^H[1-6]$/.test(e.tagName)?'#f1d88e':'#f7f5ee','important')});
}
